const http=require('http'); const product={id:10,storeId:2,title:'Порция 200 г',price:47.8,quantityStep:200,measurementUnit:'gram',measurementUnitLabel:'г',stockQuantity:10000,images:[],supplements:[]};
http.createServer((req,res)=>{const u=new URL(req.url,'http://local');let data=[];if(u.pathname.endsWith('/stores/2'))data={id:2,name:'Ласточка',address:'Тестовый магазин',isActive:true,isPickupEnabled:true};else if(u.pathname.endsWith('/stores'))data=[{id:2,name:'Ласточка',address:'Тестовый магазин',isActive:true,isPickupEnabled:true}];else if(u.pathname.includes('/products/10'))data=product;else if(u.pathname.includes('/products'))data=[product];else if(u.pathname.includes('/categories'))data=[{id:1,slug:'food',name:'Продукты',isLeaf:true}];else if(u.pathname.endsWith('/app-settings'))data={checkoutWithoutSlots:false};setTimeout(()=>{res.setHeader('Content-Type','application/json');res.end(JSON.stringify({data,hasMore:false}));},100);}).listen(4010,'127.0.0.1');
